<script setup>
import { computed, onMounted, ref } from 'vue'
import { Plus, X, History, ChevronRight, Check } from 'lucide-vue-next'
import { supabase } from '@/lib/supabase'
import { useAuthStore } from '@/stores/useAuthStore'
import { CLASS_ROSTER } from '@/data/classRoster'
import StudentProfileModal from '@/components/shared/StudentProfileModal.vue'
const auth=useAuthStore(),selectedStudentProfileId=ref(''),items=ref([]),payments=ref([]),students=ref([]),accountProfiles=ref([]),loading=ref(true),modal=ref(''),selected=ref(null),error=ref('')
const localDateTime=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)}
const form=ref({title:'',description:'',period_label:'',target_amount:0,deadline:''}),pay=ref({method:'qris',amount:0,paid_at:localDateTime(),proof:null})
const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n||0))
async function load(){
  loading.value=true;error.value=''
  const [a,p,profiles,roster]=await Promise.all([
    supabase.from('class_contributions').select('*').order('created_at',{ascending:false}),
    supabase.from('contribution_payments').select('*,student:profiles!contribution_payments_student_id_fkey(display_name)').order('submitted_at',{ascending:false}),
    supabase.from('profiles').select('id,display_name,attendance_number,role').eq('role','student').order('attendance_number',{ascending:true,nullsFirst:false}),
    supabase.rpc('get_class_roster_public')
  ])
  if(a.error)error.value=a.error.message
  if(roster.error)error.value=roster.error.code==='42P01'?'Roster kelas belum tersedia di database. Jalankan migration 20261109_finance_roster.sql di Supabase.':roster.error.message
  items.value=a.data||[]
  payments.value=await Promise.all((p.data||[]).map(async item=>{if(!item.proof_path)return item;const {data}=await supabase.storage.from('class-finance-proofs').createSignedUrl(item.proof_path,3600);return {...item,proof_url:data?.signedUrl||null}}))
  accountProfiles.value=profiles.data||[]
  const profileByAttendance=new Map(accountProfiles.value.filter(x=>x.attendance_number).map(x=>[x.attendance_number,x]))
  students.value=(roster.data?.length?roster.data:CLASS_ROSTER).map(row=>{const linked=accountProfiles.value.find(x=>x.id===row.profile_id)||profileByAttendance.get(row.attendance_number);return {...row,profile_id:row.profile_id||linked?.id||null,display_name:row.full_name}})
  loading.value=false
}
function studentName(profileId){return students.value.find(s=>s.profile_id===profileId)?.full_name||payments.value.find(p=>p.student_id===profileId)?.student?.display_name||'Siswa'}
function openStudentProfile(profileId){if(profileId)selectedStudentProfileId.value=profileId}
function closeStudentProfile(){selectedStudentProfileId.value=''}
const myRosterEntry=computed(()=>students.value.find(s=>s.profile_id===auth.user?.id)||null)
async function linkStudent(row,profileId){const {error:e}=await supabase.from('class_roster').update({profile_id:profileId||null}).eq('attendance_number',row.attendance_number);if(e)error.value=e.message;else await load()}

function total(id){return payments.value.filter(p=>p.contribution_id===id&&p.status==='approved').reduce((s,p)=>s+Number(p.amount),0)}
function percent(id){const it=items.value.find(x=>x.id===id);return it?Math.min(100,total(id)/(it.target_amount*43)*100):0}
function progressColor(id){const value=percent(id);return value>=100?'#16834c':value>=50?'#a97808':value>0?'#a64b18':'#c43c44'}
function studentPaid(contributionId,studentId){return studentId?payments.value.filter(p=>p.contribution_id===contributionId&&p.student_id===studentId&&p.status==='approved').reduce((sum,p)=>sum+Number(p.amount),0):0}
function studentClass(amount,target){const ratio=target?amount/target:0;return ratio>=1?'full':ratio>=0.5?'half':ratio>0?'low':'none'}
async function closeContribution(){const {error:e}=await supabase.from('class_contributions').update({status:'closed'}).eq('id',selected.value.id);if(e)error.value=e.message;else{modal.value='';await load()}}
async function create(){error.value='';if(!form.value.title.trim()||!form.value.period_label.trim()||Number(form.value.target_amount)<=0){error.value='Isi nama iuran, periode, dan nominal target yang valid.';return}const {error:e}=await supabase.from('class_contributions').insert({...form.value,target_amount:Number(form.value.target_amount),deadline:form.value.deadline||null,created_by:auth.user.id});if(e)error.value=e.message;else{modal.value='';await load()}}
function openPay(it){selected.value=it;pay.value={method:'qris',amount:it.target_amount,paid_at:localDateTime(),proof:null};modal.value='pay'}
async function submitPay(){error.value='';if(!Number(pay.value.amount)||Number(pay.value.amount)<=0){error.value='Nominal pembayaran harus lebih dari nol.';return}if(pay.value.method==='qris'&&!pay.value.proof){error.value='Unggah bukti pembayaran QRIS terlebih dahulu.';return}let proof_path=null;if(pay.value.proof){const file=pay.value.proof;const path=`${auth.user.id}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await supabase.storage.from('class-finance-proofs').upload(path,file);if(up.error){error.value=up.error.message;return}proof_path=path}const {error:e}=await supabase.from('contribution_payments').insert({contribution_id:selected.value.id,student_id:auth.user.id,amount:Number(pay.value.amount),method:pay.value.method,proof_path,paid_at:new Date(pay.value.paid_at).toISOString(),status:'pending'});if(e)error.value=e.message;else{modal.value='';await load()}}
async function review(p,status){const {error:e}=await supabase.from('contribution_payments').update({status,reviewed_by:auth.user.id,reviewed_at:new Date().toISOString(),rejection_reason:status==='rejected'?'Tidak memenuhi verifikasi pembayaran':null}).eq('id',p.id);if(e)error.value=e.message;else await load()}
onMounted(load)
</script>
<template><section class="contrib-page"><header class="page-head"><span class="page-head__eyebrow">Keuangan kelas · XI B2</span><div class="head-row"><div><h1 class="page-head__title">Iuran Kelas</h1><p class="page-head__desc">Iuran khusus untuk kebutuhan atau kegiatan tertentu.</p></div><button class="history-btn" @click="modal='history'" aria-label="Riwayat iuran"><History/></button></div></header>
<p v-if="error" class="error">{{error}}</p><div v-if="loading" class="empty">Memuat iuran...</div><div v-else-if="!items.filter(i=>i.status==='active').length" class="empty">Belum ada iuran kelas untuk saat ini.</div>
<div class="contrib-list"><button v-for="it in items.filter(i=>i.status==='active')" :key="it.id" class="contrib-card" @click="selected=it;modal='detail'"><span><b>{{it.title}}</b><small>{{it.description||'Iuran kelas'}}</small><small>{{it.period_label}} · {{money(it.target_amount)}} per siswa</small></span><span class="card-progress"><b :style="{color:progressColor(it.id)}">{{Math.round(percent(it.id))}}%</b><small>{{money(total(it.id))}}</small></span><ChevronRight/></button></div>
<div v-if="auth.isAdmin" class="admin-shortcut"><button @click="modal='create'"><Plus :size="17"/> Buat iuran baru</button><div v-for="p in payments.filter(p=>p.status==='pending')" :key="p.id" class="pending"><span><button type="button" class="student-profile-link" :disabled="!p.student_id" @click="openStudentProfile(p.student_id)">{{studentName(p.student_id)}}</button> · {{money(p.amount)}} <a v-if="p.proof_url" :href="p.proof_url" target="_blank" rel="noopener">Bukti</a></span><button @click="review(p,'approved')"><Check :size="14"/> Setujui</button><button @click="review(p,'rejected')">Tolak</button></div></div>
<div v-if="auth.isAdmin" class="admin-shortcut roster-admin"><h3>Hubungkan akun siswa</h3><p class="muted">Hubungkan akun dengan nomor absen agar rekap iuran menampilkan pembayaran pada siswa yang tepat.</p><div v-for="st in students" :key="st.attendance_number" class="roster-link"><span><button type="button" class="student-profile-link roster-name" :disabled="!st.profile_id" @click="openStudentProfile(st.profile_id)">{{st.attendance_number}} · {{st.full_name}}</button><small>{{st.student_number}}</small></span><select :value="st.profile_id||''" @change="linkStudent(st,$event.target.value)"><option value="">Belum dihubungkan</option><option v-for="account in accountProfiles" :key="account.id" :value="account.id">{{account.display_name}}</option></select></div></div>
<button v-if="!auth.isAdmin" class="fab" @click="items.find(i=>i.status==='active') ? openPay(items.find(i=>i.status==='active')) : null"><Plus/></button>
</section><StudentProfileModal :profile-id="selectedStudentProfileId" @close="closeStudentProfile"/>
<div v-if="modal" class="modal-bg" @click.self="modal=''"><section class="contrib-modal"><header><h2>{{modal==='create'?'Buat iuran baru':modal==='pay'?'Bayar iuran':modal==='history'?'Riwayat iuran':modal==='detail'?selected.title:'Detail iuran'}}</h2><button class="close" @click="modal=''"><X/></button></header>
<template v-if="modal==='create'"><label>Nama iuran<input v-model="form.title" placeholder="Contoh: Iuran dekorasi kelas"/></label><label>Deskripsi<textarea v-model="form.description" rows="3"/></label><label>Periode / bulan<input v-model="form.period_label" placeholder="Contoh: Kegiatan akhir semester"/></label><label>Nominal per siswa (Rp)<input v-model.number="form.target_amount" type="number" min="1"/></label><label>Deadline (opsional)<input v-model="form.deadline" type="date"/></label><button class="primary" @click="create">Terbitkan iuran</button></template>
<template v-else-if="modal==='pay'"><p class="muted">{{selected.title}} · Target {{money(selected.target_amount)}}</p><p class="muted">Pembayar: {{myRosterEntry?`${myRosterEntry.attendance_number} · ${myRosterEntry.full_name}`:(auth.user?.displayName||'Akun siswa')}}</p><label>Metode pembayaran<select v-model="pay.method"><option value="qris">QRIS</option><option value="cash">Tunai</option></select></label><div v-if="pay.method==='qris'" class="qris"><b>QRIS kelas</b><small>Gambar QRIS belum tersedia. Tambahkan qris-payment.png ke frontend/public/assets setelah kode QRIS kelas siap.</small></div><label>Nominal pembayaran (Rp)<input v-model.number="pay.amount" type="number" min="1"/></label><label v-if="pay.method==='qris'">Bukti pembayaran<input type="file" accept="image/png,image/jpeg,image/webp" @change="pay.proof=$event.target.files?.[0]||null"/></label><label>Tanggal pembayaran<input v-model="pay.paid_at" type="datetime-local"/></label><button class="primary" @click="submitPay">Kirim pembayaran</button></template>
<template v-else-if="modal==='detail'"><p>{{selected.description}}</p><p class="muted">Periode {{selected.period_label}} · Target {{money(selected.target_amount)}} per siswa</p><div class="progress"><span :style="{width:percent(selected.id)+'%',background:progressColor(selected.id)}"/></div><b>{{money(total(selected.id))}} terkumpul · {{Math.round(percent(selected.id))}}%</b><h3 class="table-title">Rekap pembayaran siswa</h3><div v-for="st in students" :key="st.attendance_number" class="pay-row"><span><button type="button" class="student-profile-link" :disabled="!st.profile_id" @click="openStudentProfile(st.profile_id)">{{st.attendance_number}} · {{st.full_name}}</button></span><b :class="studentClass(studentPaid(selected.id,st.profile_id),selected.target_amount)">{{st.profile_id?money(studentPaid(selected.id,st.profile_id)):'—'}} / {{money(selected.target_amount)}}</b></div><button v-if="!auth.isAdmin" class="primary" @click="openPay(selected)">Bayar iuran</button><button v-if="auth.isAdmin&&selected.status==='active'" class="close-campaign" @click="closeContribution">Tutup iuran</button></template>
<template v-else><div v-for="it in items" :key="it.id" class="history-card" @click="selected=it;modal='detail'"><b>{{it.title}}</b><small>{{it.description}} · {{it.period_label}}</small><small>{{money(it.target_amount)}} per siswa · {{it.status==='active'?'Aktif':'Ditutup'}}</small></div><p v-if="!items.length" class="empty">Riwayat iuran masih kosong.</p></template>
</section></div></template>
<style scoped>
.head-row{display:flex;justify-content:space-between;align-items:center}.history-btn{width:42px;height:42px;border-radius:50%;border:1px solid var(--c-border);background:white}.empty{padding:40px 18px;text-align:center;color:var(--c-text-muted);font-size:13px}.contrib-list{display:grid;gap:12px}.contrib-card{display:flex;align-items:center;gap:10px;width:100%;padding:16px;background:white;border:1px solid var(--c-border);border-radius:18px;text-align:left;color:var(--c-text)}.contrib-card>span:first-child{display:grid;gap:5px;flex:1}.contrib-card b{font-size:14px}.contrib-card small{font-size:11px;color:var(--c-text-muted)}.card-progress{text-align:right;display:grid;gap:4px}.card-progress b{color:#16834c}.admin-shortcut{margin-top:20px;display:grid;gap:10px}.admin-shortcut>button{padding:12px;border:1px solid var(--c-border);border-radius:12px;background:white;display:flex;gap:8px;align-items:center}.pending{display:flex;align-items:center;gap:6px;font-size:11px}.pending span{flex:1}.pending button{padding:7px;border:1px solid var(--c-border);border-radius:8px;background:white}.fab{position:fixed;right:22px;bottom:calc(var(--nav-h) + 30px + env(safe-area-inset-bottom));width:56px;height:56px;border:0;border-radius:50%;background:var(--c-primary);color:white;display:grid;place-items:center;box-shadow:var(--shadow-primary);z-index:35}.modal-bg{position:fixed;inset:0;background:#1e293b66;z-index:100;display:flex;align-items:flex-end;justify-content:center;padding:12px}.contrib-modal{width:min(100%,560px);max-height:88vh;overflow:auto;background:white;border-radius:24px;padding:20px}.contrib-modal header{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.contrib-modal h2{font-size:18px}.close{border:0;border-radius:50%;width:34px;height:34px;background:#f1f3f7}.contrib-modal label{display:grid;gap:6px;font-size:12px;font-weight:700;margin:12px 0}.contrib-modal input,.contrib-modal textarea,.contrib-modal select{padding:11px;border:1px solid var(--c-border);border-radius:12px;font:inherit}.primary{width:100%;padding:13px;border:0;border-radius:12px;background:var(--c-primary);color:white;font-weight:800;margin-top:12px}.muted{font-size:12px;color:var(--c-text-muted)}.qris img{display:block;max-width:180px;max-height:180px;object-fit:contain;margin:0 auto 10px}.qris{padding:18px;background:#f4f7fb;border-radius:12px;font-size:12px;color:var(--c-text-muted)}.progress{height:9px;background:#edf0f5;border-radius:10px;overflow:hidden;margin:14px 0 8px}.progress span{display:block;height:100%;background:#23a36b}.table-title{font-size:14px;margin-top:20px}.pay-row b{padding:4px 7px;border-radius:7px}.pay-row b.none{background:#ffe8e8;color:#c43c44}.pay-row b.low{background:#f6d1b7;color:#8e3d14}.pay-row b.half{background:#fff0b8;color:#8b6500}.pay-row b.full{background:#d9f5e4;color:#147a43}.close-campaign{width:100%;padding:12px;border:1px solid var(--c-border);border-radius:12px;background:#fff7e4;color:#8d6400;font-weight:700;margin-top:12px}.pay-row{display:flex;justify-content:space-between;padding:9px 0;border-top:1px solid var(--c-border);font-size:11px}.history-card{display:grid;gap:4px;padding:12px 0;border-top:1px solid var(--c-border)}.history-card small{font-size:11px;color:var(--c-text-muted)}.roster-admin h3{font-size:14px}.roster-link{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 0;border-top:1px solid var(--c-border)}.roster-link span{display:grid;gap:3px;min-width:0}.roster-link b{font-size:11px}.roster-link small{font-size:10px;color:var(--c-text-muted)}.roster-link select{max-width:170px;min-width:120px;padding:7px;border:1px solid var(--c-border);border-radius:9px;background:white;font:inherit;font-size:11px}.error{color:#b42b36;background:#fff0f0;padding:10px;border-radius:10px}.student-profile-link{display:inline;text-align:left;padding:0;border:0;background:transparent;color:inherit;font:inherit;font-weight:inherit;text-decoration:underline;text-decoration-color:var(--c-border);text-underline-offset:3px;cursor:pointer}.student-profile-link:hover{color:var(--c-primary)}.student-profile-link:disabled{cursor:default;text-decoration:none}.roster-name{font-size:11px;font-weight:700}@media(min-width:700px){.modal-bg{align-items:center}}
</style>
